// retrySource is sdk.MetadataSource scripted per Merge call: it fails the first
// failN Merge calls then succeeds. noData makes the success produce an empty
// namespace (validateNamespace -> nil -> no_data). applies=false drives
// outcomeSkipped; a resolver error drives outcomeUnavailable. It reuses the
// wrapNamespace helper from enrich_test.go (same package).
type retrySource struct {
	sdk.UnsupportedSearch // the interactive search pair: unsupported (identify-match-override)
	id                    string
	applies               bool
	failN                 int
	noData                bool
	mergeCalls            int
}

var _ sdk.MetadataSource = (*retrySource)(nil)

func (s *retrySource) Match(context.Context, *metadatav1.MatchRequest) (*metadatav1.MatchResult, error) {
	return &metadatav1.MatchResult{Applies: s.applies}, nil
}
func (s *retrySource) BuildRequest(context.Context, *metadatav1.BuildRequestRequest) (*metadatav1.BuildRequestResponse, error) {
	return &metadatav1.BuildRequestResponse{}, nil
}
func (s *retrySource) Convert(context.Context, *metadatav1.ConvertRequest) (*metadatav1.ConvertResult, error) {
	md, _ := structpb.NewStruct(map[string]any{"title": "X"})
	return &metadatav1.ConvertResult{Metadata: md}, nil
}
func (s *retrySource) Merge(_ context.Context, req *metadatav1.MergeRequest) (*metadatav1.MergeResult, error) {
	s.mergeCalls++
	if s.mergeCalls <= s.failN {
		return nil, fmt.Errorf("scripted merge failure #%d", s.mergeCalls)
	}
	incoming := req.GetIncoming()
	if s.noData {
		incoming = nil // sources.<id> absent -> validateNamespace returns nil -> no_data
	}
	return &metadatav1.MergeResult{Document: wrapNamespace(s.id, incoming, false)}, nil
}

// resolverOf builds a metadataResolver returning src (or resolveErr for the
// unavailable case).
func resolverOf(src sdk.MetadataSource, resolveErr error) metadataResolver {
	return func(string, string) (sdk.MetadataSource, error) { return src, resolveErr }
}

// TestRunSourceRetryable is the S3 joint: the retry loop over runSource. Table-
// driven over success-short-circuit, transient->backoff->exhausted, recovery,
// no_data-immediate, skipped, and unavailable. (ctx-cancel is a separate test.)
func TestRunSourceRetryable(t *testing.T) {
	mod := module.Module{ID: "tv", MediaType: "tv"}
	base := &scannerv1.IdentifyResult{}

	cases := []struct {
		name         string
		src          *retrySource
		resolveErr   error
		wantStatus   string
		wantAttempts int
		wantMerge    int
		checkNS      bool // assert the success namespace was carried through
	}{
		{
			name:       "success on attempt 1 short-circuits, no ledger",
			src:        &retrySource{id: "tv-parser", applies: true, failN: 0},
			wantStatus: "", wantAttempts: 1, wantMerge: 1, checkNS: true,
		},
		{
			name:       "transient fail x3 -> terminal exhausted",
			src:        &retrySource{id: "tv-parser", applies: true, failN: 10}, // always fails
			wantStatus: "exhausted", wantAttempts: 3, wantMerge: 3,
		},
		{
			name:       "fail then succeed -> recovered, no ledger",
			src:        &retrySource{id: "tv-parser", applies: true, failN: 1},
			wantStatus: "", wantAttempts: 2, wantMerge: 2,
		},
		{
			name:       "no_data (empty namespace) terminal-immediate",
			src:        &retrySource{id: "tv-parser", applies: true, failN: 0, noData: true},
			wantStatus: "no_data", wantAttempts: 1, wantMerge: 1,
		},
		{
			name:       "applies=false -> skipped, no retry, no ledger",
			src:        &retrySource{id: "tv-parser", applies: false},
			wantStatus: "", wantAttempts: 1, wantMerge: 0,
		},
		{
			name:       "plugin not loaded -> unavailable, no retry, no ledger",
			src:        &retrySource{id: "tv-parser", applies: true},
			resolveErr: fmt.Errorf("not loaded"),
			wantStatus: "", wantAttempts: 1, wantMerge: 0,
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			tc.src.mergeCalls = 0
			sr, status, attempts := runSourceRetryable(
				context.Background(), resolverOf(tc.src, tc.resolveErr),
				binding("tv-parser", 1, true), mod, base, map[string]any{}, nil, nil, 3, time.Millisecond,
			)
			if status != tc.wantStatus {
				t.Fatalf("ledgerStatus = %q, want %q", status, tc.wantStatus)
			}
			if attempts != tc.wantAttempts {
				t.Fatalf("attempts = %d, want %d", attempts, tc.wantAttempts)
			}
			if tc.src.mergeCalls != tc.wantMerge {
				t.Fatalf("mergeCalls = %d, want %d", tc.src.mergeCalls, tc.wantMerge)
			}
			if tc.checkNS {
				if sr.namespace == nil || sr.namespace["title"] != "X" {
					t.Fatalf("success namespace not carried: %+v", sr.namespace)
				}
			}
		})
	}
}

// TestRunSourceRetryable_CtxCancel covers B7: a ctx that expires mid-backoff
// returns promptly with ledgerStatus="" (NOT terminal) and a non-success kind
// (the zero-value outcomeSucceeded must never leak through on cancel).
func TestRunSourceRetryable_CtxCancel(t *testing.T) {
	mod := module.Module{ID: "tv", MediaType: "tv"}
	src := &retrySource{id: "tv-parser", applies: true, failN: 10} // always fails
	// backoff (100ms) >> ctx deadline (3ms) >> runSource (sub-ms): attempt 1 fails
	// fast, then the backoff select is resolved by the ctx deadline, not the timer.
	ctx, cancel := context.WithTimeout(context.Background(), 3*time.Millisecond)
	defer cancel()
	sr, status, attempts := runSourceRetryable(
		ctx, resolverOf(src, nil), binding("tv-parser", 1, true), mod,
		&scannerv1.IdentifyResult{}, map[string]any{}, nil, nil, 3, 100*time.Millisecond,
	)
	if status != "" {
		t.Fatalf("ledgerStatus = %q, want \"\" (ctx abort is not a terminal outcome)", status)
	}
	if attempts < 1 {
		t.Fatalf("attempts = %d, want >= 1 (one attempt ran before ctx expired mid-backoff)", attempts)
	}
	if sr.kind == outcomeSucceeded {
		t.Fatalf("returned kind = outcomeSucceeded on cancel (zero-value leak); want a non-success kind")
	}
}
